SELECT budget_bucket, num_departments FROM (SELECT CASE WHEN budget >= 4072000 THEN 'high' WHEN budget >= 1151000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(*) AS num_departments FROM departments WHERE dept_name NOT IN ('Marketing', 'Engineering', 'HR') GROUP BY CASE WHEN budget >= 4072000 THEN 'high' WHEN budget >= 1151000 THEN 'mid' ELSE 'low' END) AS t WHERE num_departments > 8
